(()=>{'use strict';const el=(tag,cls,text)=>{const n=document.createElement(tag);n.className=cls;if(text)n.textContent=text;return n;};for(const id of['bloom','arcade','cassette','cosmic'])OBStartLayouts.register(id,{mount(ctx){const deck=el('div','ob-deck');deck.setAttribute('aria-label','App launcher');if(id==='cassette'){const reels=el('div','ob-reels');reels.setAttribute('aria-hidden','true');reels.append(el('i','ob-reel'),el('i','ob-reel'));deck.append(reels);}if(id==='bloom'||id==='cosmic'){const shape=el('div','ob-core',id==='bloom'?'✿':'✦');shape.setAttribute('aria-hidden','true');deck.append(shape);}const name=el('output','ob-launch-name');name.dataset.launchName='';deck.append(name);const row=el('div','ob-launch-controls');for(const [text,label,action]of [['◀','Previous app',()=>ctx.select(-1)],['↗','Open selected app',()=>ctx.activate()],['▶','Next app',()=>ctx.select(1)]]){const b=el('button','ob-launch-control',text);b.type='button';b.setAttribute('aria-label',label);b.addEventListener('click',action);row.append(b);}deck.append(row);ctx.surface.append(deck);return()=>deck.remove();}});})();
